import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Section, SectionProps } from '../../shared/section/section'
import { Stack } from '../../shared/stack/Stack'
import {
  OutcomesSectionItem,
  OutcomesSectionItemProps,
} from './outcomes-section-item'

type OutcomesSectionProps = Pick<SectionProps, 'headline' | 'overline'> & {
  outcomes: OutcomesSectionItemProps[]
}

export const OutcomesSection = forwardRef(function OutcomesSection(
  { outcomes, ...props },
  ref,
) {
  return (
    <Section {...props} ref={ref}>
      <Stack direction={'column'} gap={4 * 6}>
        {outcomes.map((outcome, index) => (
          <OutcomesSectionItem
            css={{ flex: 1 }}
            key={outcome.role + index}
            {...outcome}
          />
        ))}
      </Stack>
    </Section>
  )
}) as Polymorphic<'section', OutcomesSectionProps>
