import { forwardRef, ReactNode } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Card } from '../card/card'

export type HeroTeaserProps = {
  introduction: () => ReactNode
  illustration: () => ReactNode
}

export const HeroTeaser = forwardRef(function HeroTeaser(
  { as: Component = 'section', introduction, illustration, ...props },
  ref,
) {
  const glowBoxShadow = '0 0 80px rgba(32, 217, 176, 0.2) !important'

  return (
    <Component
      className="grid gap-12 pb-20 pt-8 md:grid-cols-[1.1fr_0.9fr]"
      {...props}
      ref={ref}
    >
      {introduction()}

      <Card
        size="md"
        className="backdrop-blur self-center"
        css={{ boxShadow: glowBoxShadow }}
      >
        {illustration()}
      </Card>
    </Component>
  )
}) as Polymorphic<'section', HeroTeaserProps>
