import { forwardRef, ReactNode } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Stack } from '../stack/Stack'

type BadgeProps = {
  size: 'sm' | 'lg'
  variant: 'outline'
  iconStart?: ReactNode
  iconEnd?: ReactNode
}

const sizeClasses: Record<BadgeProps['size'], string> = {
  sm: 'px-4 py-2 text-xs',
  lg: 'px-6 py-3 text-sm',
}

const variantClasses: Record<BadgeProps['variant'], string> = {
  outline:
    'border border-ink-200/60 text-ink-600 hover:border-ink-400 dark:border-ink-600 dark:text-ink-200',
}

export const Badge = forwardRef(function Badge(
  { as, size, variant, iconStart, iconEnd, children, className, ...props },
  ref,
) {
  const classNames = [
    'whitespace-nowrap rounded-full font-semibold uppercase tracking-[0.2em]',
    sizeClasses[size],
    variantClasses[variant],
    className,
  ]
    .filter(Boolean)
    .join(' ')

  return (
    <Stack
      as={as ?? 'span'}
      className={classNames}
      align="center"
      gap={8}
      {...props}
      ref={ref}
    >
      {iconStart}
      {children}
      {iconEnd}
    </Stack>
  )
}) as Polymorphic<'span', BadgeProps>
