import { Check } from 'lucide-react'
import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Card } from '../../shared/card/card'
import { Stack } from '../../shared/stack/Stack'
import { Typography } from '../../shared/typography/typography'

export type ServicesSectionItemProps = {
  headline: string
  overline: string
  bullets: string[]
}

export const ServicesSectionItem = forwardRef(function ServicesSectionItem(
  { overline, headline, bullets, ...props },
  ref,
) {
  return (
    <Card size="lg" {...props} ref={ref}>
      <Typography scale="overline" emphasis="muted">
        {overline}
      </Typography>
      <Typography as="h3" scale="h3" emphasis="strong" className="mt-4">
        {headline}
      </Typography>
      <div className="mt-6 space-y-4">
        {bullets.map((point) => (
          <Stack key={point} align="center" gap={3 * 4}>
            <span className="grid h-6 w-6 place-items-center rounded-full bg-neon-500/15 text-neon-500">
              <Check className="h-4 w-4" />
            </span>
            <Typography as="span" scale="body" emphasis="default">
              {point}
            </Typography>
          </Stack>
        ))}
      </div>
    </Card>
  )
}) as Polymorphic<'div', ServicesSectionItemProps>
