import { forwardRef, useEffect, useMemo, useState } from 'react'
import { useTranslation } from 'react-i18next'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Card } from '../../shared/card/card'
import { Stack } from '../../shared/stack/Stack'
import { Typography } from '../../shared/typography/typography'
import { HeroSectionIllustrationDiagramStep } from './hero-section-illustration-diagram-step'
import { HeroSectionIllustrationDiagramStepConnection } from './hero-section-illustration-diagram-step-connection'

export const HeroSectionIllustration = forwardRef(
  function HeroSectionIllustration({ ...props }, ref) {
    const { t } = useTranslation()
    const [activeStepIndex, setActiveStepIndex] = useState(0)

    const headline = t('hero-section.illustration.headline')
    const steps = useMemo(
      () =>
        [
          { label: t('hero-section.illustration.start-event'), type: 'event' },
          {
            label: t('hero-section.illustration.first-activity'),
            type: 'task',
          },
          {
            label: t('hero-section.illustration.second-activity'),
            type: 'task',
          },
          { label: t('hero-section.illustration.end-event'), type: 'event' },
        ] as const,
      [t],
    )

    useEffect(() => {
      const intervalId = window.setInterval(() => {
        setActiveStepIndex((currentIndex) => (currentIndex + 1) % steps.length)
      }, 2000)

      return () => window.clearInterval(intervalId)
    }, [steps.length])

    return (
      <Card size="sm" {...props} ref={ref}>
        <Typography scale="overline" emphasis="muted">
          {headline}
        </Typography>

        <Stack direction="column" align="center" gap={4 * 4} className="mt-5">
          {steps.map((step, index) => (
            <Stack
              key={`${step.label}-${index}`}
              direction="column"
              align="center"
              gap={4 * 4}
            >
              <HeroSectionIllustrationDiagramStep
                {...step}
                emphasized={index === activeStepIndex}
              />
              {index < steps.length - 1 && (
                <HeroSectionIllustrationDiagramStepConnection />
              )}
            </Stack>
          ))}
        </Stack>
      </Card>
    )
  },
) as Polymorphic<'div'>
