import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Stack } from '../stack/Stack'
import { Typography } from '../typography/typography'

export type SectionProps = {
  headline: string
  overline?: string
}

export const Section = forwardRef(function Section(
  { as, headline, overline, children, ...props },
  ref,
) {
  return (
    <Stack
      as={as ?? 'section'}
      direction="column"
      gap={4 * 8}
      className="py-16"
      {...props}
      ref={ref}
    >
      <Stack
        direction={{ sm: 'column', md: 'row' }}
        justify="space-between"
        align={{ md: 'center' }}
        gap={4 * 3}
      >
        <Typography as="h2" scale="h3" emphasis="strong" className="mt-4">
          {headline}
        </Typography>
        {overline && (
          <Typography scale="overline" emphasis="muted">
            {overline}
          </Typography>
        )}
      </Stack>
      {children}
    </Stack>
  )
}) as Polymorphic<'section', SectionProps>
