import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Card } from '../../shared/card/card'
import { Stack } from '../../shared/stack/Stack'
import { Typography } from '../../shared/typography/typography'

export type OutcomesSectionItemProps = {
  industry: string
  role: string
  description: string
}

export const OutcomesSectionItem = forwardRef(function OutcomesSectionItem(
  { industry, role, description, ...props },
  ref,
) {
  return (
    <Card size="md" {...props} ref={ref}>
      <Stack align="center" wrap="wrap" gap={3 * 4}>
        <Typography scale="subtitle-small" emphasis="strong">
          {role}
        </Typography>
        <span className="h-1.5 w-1.5 rounded-full bg-neon-500" />
        <Typography scale="overline" emphasis="muted">
          {industry}
        </Typography>
      </Stack>
      <Typography scale="body-small" emphasis="default" className="mt-3">
        {description}
      </Typography>
    </Card>
  )
}) as Polymorphic<'div', OutcomesSectionItemProps>
