import { ArrowRight } from 'lucide-react'
import { forwardRef } from 'react'
import { useTranslation } from 'react-i18next'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Button } from '../../shared/button/button'
import { HeroTeaser } from '../../shared/hero-teaser/hero-teaser'
import { HeroTeaserIntroduction } from '../../shared/hero-teaser/hero-teaser-introduction'
import { Stack } from '../../shared/stack/Stack'
import { HeroSectionIllustration } from './hero-section-illustration'

type HeroSectionProps = {
  headline: string
  description: string
}

export const HeroSection = forwardRef(function HeroSection(
  { headline, description, ...props },
  ref,
) {
  const { t } = useTranslation()

  return (
    <HeroTeaser
      {...props}
      ref={ref}
      introduction={() => (
        <HeroTeaserIntroduction headline={headline} description={description}>
          <Stack className="mt-10" align="center" wrap="wrap" gap={4 * 4}>
            <Button
              size="lg"
              variant="primary"
              onClick={() =>
                window.scrollTo({
                  top: document.body.scrollHeight,
                  behavior: 'smooth',
                })
              }
              iconEnd={<ArrowRight className="h-4 w-4" />}
            >
              {t('hero-section.contact-me')}
            </Button>
          </Stack>
        </HeroTeaserIntroduction>
      )}
      illustration={() => <HeroSectionIllustration />}
    />
  )
}) as Polymorphic<'section', HeroSectionProps>
