import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Badge } from '../../shared/badge/badge'

export type TechnologiesSectionCarouselItemProps = {
  item: string
}

export const TechnologiesSectionCarouselItem = forwardRef(
  function TechnologiesSectionCarouselItem({ item, ...props }, ref) {
    return (
      <Badge size="sm" variant="outline" {...props} ref={ref}>
        {item}
      </Badge>
    )
  },
) as Polymorphic<'span', TechnologiesSectionCarouselItemProps>
