import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Card } from '../../shared/card/card'
import { Section, SectionProps } from '../../shared/section/section'
import { TechnologiesSectionCarousel } from './technologies-section-carousel'
import { TechnologiesSectionCarouselItem } from './technologies-section-carousel-item'

export type TechnologiesSectionProps = Pick<
  SectionProps,
  'headline' | 'overline'
> & {
  items: string[]
}

export const TechnologiesSection = forwardRef(function TechnologiesSection(
  { items, ...props },
  ref,
) {
  return (
    <Section {...props} ref={ref}>
      <Card size="md" className="overflow-hidden">
        <TechnologiesSectionCarousel>
          {[...items, ...items].map((item, index) => (
            <TechnologiesSectionCarouselItem
              key={`${item}-${index}`}
              item={item}
            />
          ))}
        </TechnologiesSectionCarousel>
      </Card>
    </Section>
  )
}) as Polymorphic<'section', TechnologiesSectionProps>
