import { ComponentType, forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Card } from '../../shared/card/card'
import { Typography } from '../../shared/typography/typography'

export type PhilosophySectionItemProps = {
  title: string
  description: string
  icon: ComponentType<{ className?: string }>
}

export const PhilosophySectionItem = forwardRef(function PhilosophySectionItem(
  { title, description, icon: Icon, ...props },
  ref,
) {
  return (
    <Card size="md" {...props} ref={ref}>
      <Icon className="h-6 w-6 text-neon-500" />
      <Typography as="h4" scale="h4" emphasis="strong" className="mt-4">
        {title}
      </Typography>
      <Typography scale="body-small" emphasis="default" className="mt-3">
        {description}
      </Typography>
    </Card>
  )
}) as Polymorphic<'div', PhilosophySectionItemProps>
