import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Section, SectionProps } from '../../shared/section/section'
import {
  PhilosophySectionItem,
  PhilosophySectionItemProps,
} from './philosophy-section-item'

type PhilosophySectionProps = Pick<SectionProps, 'headline' | 'overline'> & {
  claims: PhilosophySectionItemProps[]
}

export const PhilosophySection = forwardRef(function PhilosophySection(
  { claims, ...props },
  ref,
) {
  return (
    <Section {...props} ref={ref}>
      <div className="grid gap-6 md:grid-cols-3">
        {claims.map((item) => (
          <PhilosophySectionItem key={item.title} {...item} />
        ))}
      </div>
    </Section>
  )
}) as Polymorphic<'section', PhilosophySectionProps>
