import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Stack } from '../stack/Stack'
import { Typography } from '../typography/typography'

export type HeroTeaserIntroductionProps = {
  headline: string
  description: string
}

export const HeroTeaserIntroduction = forwardRef(function HeroTeaser(
  { headline, description, children, ...props },
  ref,
) {
  return (
    <Stack direction="column" justify="center" gap={4 * 6} {...props} ref={ref}>
      <Typography scale="h1" emphasis="strong">
        {headline}
      </Typography>
      <Typography scale="body-large" emphasis="default">
        {description}
      </Typography>
      <Stack className="" align="center" wrap="wrap" gap={4 * 4}>
        {children}
      </Stack>
    </Stack>
  )
}) as Polymorphic<'div', HeroTeaserIntroductionProps>
