import { ComponentType, forwardRef } from 'react'

import { Polymorphic } from '../../utils/PolymorphicUtils'
import { Container } from '../shared/container/container'
import { HeroSection } from './hero-section/hero-section'
import { OutcomesSection } from './outcomes-section/outcomes-section'
import { PhilosophySection } from './philosophy-section/philosophy-section'
import { ServicesSection } from './services-section/services-section'
import { TechnologiesSection } from './technologies-section/technologies-section'

export type ProfileData = {
  name: string
  image: string
}

export type ContactData = {
  overline: string
  headline: string
  phone: string
  email: string
}

export type HeroData = {
  headline: string
  description: string
}

export type PhilosophyData = {
  headline: string
  overline: string
  claims: Array<{
    title: string
    description: string
    icon: ComponentType<{ className?: string }>
  }>
}

export type ServicesData = {
  headline: string
  overline: string
  offers: Array<{
    headline: string
    overline: string
    bullets: Array<string>
  }>
}

export type OutcomesData = {
  headline: string
  overline: string
  outcomes: Array<{
    industry: string
    role: string
    description: string
  }>
}

export type TechnologiesData = {
  headline: string
  overline: string
  items: Array<string>
}

export type LandingPageData = {
  profile: ProfileData
  contacts: ContactData
  hero: HeroData
  philosophy: PhilosophyData
  services: ServicesData
  outcomes: OutcomesData
  technologies: TechnologiesData
}

export type LandingPageProps = LandingPageData

export const LandingPage = forwardRef(function LandingPage(
  {
    as: Component = 'main',
    hero,
    philosophy,
    services,
    outcomes,
    technologies,
    className,
    ...props
  },
  ref,
) {
  return (
    <Component
      className={`relative z-10 flex-1 ${className ?? ''}`}
      {...props}
      ref={ref}
    >
      <Container className="space-y-16 flex flex-col">
        <HeroSection {...hero} />
        <PhilosophySection {...philosophy} />
        <ServicesSection {...services} />
        <OutcomesSection {...outcomes} />
        <TechnologiesSection {...technologies} />
      </Container>
    </Component>
  )
}) as Polymorphic<'main', LandingPageProps>
