import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Section, SectionProps } from '../../shared/section/section'
import {
  ServicesSectionItem,
  ServicesSectionItemProps,
} from './services-section-item'

type ServicesSectionProps = SectionProps & {
  offers: ServicesSectionItemProps[]
}

export const ServicesSection = forwardRef(function ServicesSection(
  { offers, ...props },
  ref,
) {
  return (
    <Section {...props} ref={ref}>
      <div className="grid gap-8 md:grid-cols-2">
        {offers.map((offer) => (
          <ServicesSectionItem key={offer.headline} {...offer} />
        ))}
      </div>
    </Section>
  )
}) as Polymorphic<'section', ServicesSectionProps>
