import { forwardRef } from 'react'

import { Polymorphic } from '../../../utils/PolymorphicUtils'
import { Stack } from '../../shared/stack/Stack'
import { Typography } from '../../shared/typography/typography'

export type HeroSectionIllustrationDiagramStepProps = {
  type: 'event' | 'task'
  label: string
  emphasized?: boolean
}

export const HeroSectionIllustrationDiagramStep = forwardRef(
  function HeroSectionIllustrationDiagramStep(
    { type, label, emphasized = false, ...props },
    ref,
  ) {
    const activityClasses = emphasized
      ? 'border border-neon-500/70 bg-neon-500/10 dark:border-neon-500/60 dark:bg-neon-500/15'
      : 'border border-ink-200 bg-white/90 dark:border-ink-600 dark:bg-ink-900 '

    const eventClasses = emphasized
      ? 'border-2 border-neon-500/70 bg-neon-500/10 dark:border-neon-500/60 dark:bg-neon-500/15'
      : 'border-2 border-ink-200 bg-white/90 dark:border-ink-600 dark:bg-ink-900'

    const labelClasses = 'text-[10px] uppercase tracking-[0.2em]'

    const stepTransitionStyle = {
      transition:
        'transform 1000ms ease-in-out, box-shadow 1000ms ease-in-out, background-color 1000ms ease-in-out, border-color 1000ms ease-in-out',
    }

    const labelTransitionStyle = {
      transition: 'color 1000ms ease-in-out',
    }

    return (
      <Stack direction="column" align="center" gap={2 * 4} {...props} ref={ref}>
        {type === 'event' ? (
          <Stack
            direction="column"
            align="center"
            gap={4}
            className="group hover:-translate-y-0.5 hover:scale-[1.02]"
            style={{ transition: 'transform 1000ms ease-in-out' }}
          >
            <div
              className={`h-10 w-10 rounded-full group-hover:shadow-md ${eventClasses}`}
              style={stepTransitionStyle}
            />
            <Typography
              scale="caption"
              emphasis="muted"
              className={`${labelClasses}`}
              style={labelTransitionStyle}
            >
              {label}
            </Typography>
          </Stack>
        ) : (
          <div
            className={`grid h-12 w-32 place-items-center rounded-xl hover:-translate-y-0.5 hover:scale-[1.02] hover:shadow-md ${activityClasses}`}
            style={stepTransitionStyle}
          >
            <Typography
              scale="caption"
              emphasis={emphasized ? 'strong' : 'muted'}
              className={`${labelClasses}`}
              style={labelTransitionStyle}
            >
              {label}
            </Typography>
          </div>
        )}
      </Stack>
    )
  },
) as Polymorphic<'div', HeroSectionIllustrationDiagramStepProps>
